<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>팀 과제 보드</title>
  <link rel="stylesheet" href="style.css" />
</head>
<body>
  <header>
    <h1>팀 과제 보드</h1>
    <p class="sub">마감일과 역할 분담을 한 화면에서</p>
  </header>

  <main>
    <section class="panel">
      <h2>팀원</h2>
      <form id="member-form">
        <input id="member-name" placeholder="이름" required maxlength="20" />
        <input id="member-role" placeholder="역할 (예: 발표, 자료조사)" maxlength="30" />
        <button type="submit">추가</button>
      </form>
      <ul id="member-list"></ul>
    </section>

    <section class="panel">
      <h2>과제</h2>
      <form id="task-form">
        <input id="task-title" placeholder="할 일" required maxlength="60" />
        <input id="task-due" type="date" required />
        <select id="task-owner"></select>
        <button type="submit">추가</button>
      </form>
    </section>

    <section class="panel">
      <div class="view-head">
        <h2>보기</h2>
        <div class="tabs">
          <button data-view="timeline" class="active">마감일순</button>
          <button data-view="members">팀원별</button>
        </div>
      </div>
      <div id="summary"></div>
      <div id="view"></div>
    </section>
  </main>

  <script src="app.js"></script>
</body>
</html>

